    private static function reviewQueue(PDO $db):array
    {
        return $db->query("SELECT fs.id,fs.assignment_id,fs.submitted_at,f.title,f.form_type,COALESCE(fa.subject_user_id,fa.user_id) subject_user_id,CONCAT(subject.first_name,' ',subject.last_name) subject_name,CONCAT(submitter.first_name,' ',submitter.last_name) submitter_name,fs.submitted_by_user_id,p.title production_title FROM form_submissions fs JOIN form_assignments fa ON fa.id=fs.assignment_id JOIN forms f ON f.id=fs.form_id JOIN users subject ON subject.id=COALESCE(fa.subject_user_id,fa.user_id) JOIN users submitter ON submitter.id=fs.submitted_by_user_id LEFT JOIN productions p ON p.id=fa.production_id WHERE fs.status='submitted' AND f.review_required=1 ORDER BY fs.submitted_at,fs.id")->fetchAll();
    }

