        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forms review · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/family-forms.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/forms',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Forms','Review queue',$basePath,$sub);?><div class="ff-page"><?php if($flash):?><div class="ff-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="ff-hero"><div><small>STAFF REVIEW</small><h2>Review the person the form is about—not just who submitted it.</h2><p>Guardian-submitted Student forms remain attached to the Student while Connect records the adult who completed the response.</p></div><div><b><?=count($rows)?></b><span>awaiting review</span></div></section><?php if(!$rows):?><section class="ff-empty"><h3>Nothing is waiting for review.</h3><p>New review-required submissions will appear here automatically.</p></section><?php else:?><section class="ff-list"><?php foreach($rows as $row):$onBehalf=(int)$row['submitted_by_user_id']!==(int)$row['subject_user_id'];?><a class="ff-row" href="<?=$u('/admin/forms/review?id='.(int)$row['id'])?>"><div class="ff-person"><small>FOR</small><b><?=$e((string)$row['subject_name'])?></b></div><div class="ff-main"><small><?=$row['production_title']?$e((string)$row['production_title']):'CTSMD'?> · <?=$e(strtoupper(str_replace('_',' ',(string)$row['form_type'])))?></small><h3><?=$e((string)$row['title'])?></h3><p>Submitted by <?=$e((string)$row['submitter_name'])?><?=$onBehalf?' · guardian/on behalf':''?> · <?=date('M j, Y · g:i A',strtotime((string)$row['submitted_at']))?></p></div><span class="ff-status">Review</span></a><?php endforeach;?></section><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
