    private static function reviewItem(PDO $db,int $id):?array
    {
        if($id<1)return null;$s=$db->prepare("SELECT fs.*,f.title,f.form_type,f.review_required,fa.status assignment_status,COALESCE(fa.subject_user_id,fa.user_id) subject_user_id,CONCAT(subject.first_name,' ',subject.last_name) subject_name,CONCAT(submitter.first_name,' ',submitter.last_name) submitter_name,p.title production_title FROM form_submissions fs JOIN form_assignments fa ON fa.id=fs.assignment_id JOIN forms f ON f.id=fs.form_id JOIN users subject ON subject.id=COALESCE(fa.subject_user_id,fa.user_id) JOIN users submitter ON submitter.id=fs.submitted_by_user_id LEFT JOIN productions p ON p.id=fa.production_id WHERE fs.id=:id LIMIT 1");$s->execute(['id'=>$id]);return$s->fetch()?:null;
    }

    private static function review(PDO $db,string $basePath,array $user,array $r):never
    {
        self::csrf();$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['reviewer_note']??''));try{if(!in_array($decision,['approve','reject'],true))throw new RuntimeException('Choose approve or return.');if(mb_strlen($note)>2000)throw new RuntimeException('Keep the review note under 2,000 characters.');$db->beginTransaction();$approved=$decision==='approve';$db->prepare('UPDATE form_submissions SET status=:status,reviewer_user_id=:reviewer,reviewer_note=:note,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$approved?'approved':'rejected','reviewer'=>(int)$user['id'],'note'=>$note!==''?$note:null,'id'=>(int)$r['id']]);$db->prepare('UPDATE form_assignments SET status=:status,completed_at=:completed WHERE id=:id')->execute(['status'=>$approved?'completed':'missing','completed'=>$approved?date('Y-m-d H:i:s'):null,'id'=>(int)$r['assignment_id']]);self::notify($db,(int)$r['submitted_by_user_id'],'form_review',(int)$r['id'],$approved?'Form approved · '.$r['title']:'Form needs another look · '.$r['title'],$approved?'The form submitted for '.$r['subject_name'].' was approved.':'The form submitted for '.$r['subject_name'].' was returned for an update.'.($note!==''?' Reviewer note: '.$note:''),'/forms/view?id='.(int)$r['assignment_id']);self::audit($db,(int)$user['id'],$approved?'form.approved':'form.rejected','form_submission',(int)$r['id'],$approved?'Approved household form submission.':'Returned household form submission.',['subject_user_id'=>(int)$r['subject_user_id'],'submitted_by_user_id'=>(int)$r['submitted_by_user_id']]);$db->commit();self::flash('success',$approved?'Form approved.':'Form returned for changes.');self::redirect($basePath.'/admin/forms');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();self::flash('error',$e instanceof RuntimeException?$e->getMessage():'The review could not be saved.');self::redirect($basePath.'/admin/forms/review?id='.(int)$r['id']);}
    }

    private static function reviewPage(PDO $db,string $basePath,array $user,array $r):never
    {
        $answers=DynamicFormService::answers($db,(int)$r['id']);$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review <?=$e((string)$r['title'])?> · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/family-forms.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/forms/review',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Forms','Review submission',$basePath,[['label'=>'Review queue','href'=>'/admin/forms','active'=>true],['label'=>'Manage forms','href'=>'/admin/forms/manage','active'=>false],['label'=>'Form builder','href'=>'/admin/forms/build','active'=>false],['label'=>'Group assignment','href'=>'/admin/forms/group-assign','active'=>false]]);?><div class="ff-page narrow"><?php if($flash):?><div class="ff-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="ff-form-head"><small><?=$r['production_title']?$e((string)$r['production_title']):'CTSMD'?></small><h2><?=$e((string)$r['title'])?></h2><p><b>For:</b> <?=$e((string)$r['subject_name'])?><br><b>Submitted by:</b> <?=$e((string)$r['submitter_name'])?><?=((int)$r['submitted_by_user_id']!==(int)$r['subject_user_id'])?' · guardian/on behalf':''?></p></section><section class="ff-review"><?php if($answers):?><?php foreach($answers as $a):?><article><small><?=$e(strtoupper(str_replace('_',' ',(string)$a['field_type'])))?></small><h3><?=$e((string)$a['field_label'])?></h3><p><?=is_array($a['answer'])?$e(implode(', ',$a['answer'])):$e(is_bool($a['answer'])?($a['answer']?'Acknowledged':'Not acknowledged'):(string)$a['answer'])?></p></article><?php endforeach;?><?php else:?><article><h3>Legacy response</h3><?php if($r['typed_signature']):?><p>Signature: <?=$e((string)$r['typed_signature'])?></p><?php endif;?><?php if($r['response_text']):?><p><?=nl2br($e((string)$r['response_text']))?></p><?php endif;?></article><?php endif;?></section><?php if($r['status']==='submitted'):?><form class="ff-form" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['family_forms_csrf'])?>"><input type="hidden" name="submission_id" value="<?=(int)$r['id']?>"><label>Reviewer note<textarea name="reviewer_note" rows="5" maxlength="2000"></textarea></label><footer><button type="submit" name="decision" value="reject">Return for changes</button><button class="button" type="submit" name="decision" value="approve">Approve</button></footer></form><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function csrf():void{if(!hash_equals((string)($_SESSION['family_forms_csrf']??''),(string)($_POST['csrf_token']??'')))throw new RuntimeException('Your session token expired. Please try again.');}
    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
    private static function notify(PDO $db,int $recipient,string $type,int $source,string $title,string $body,string $path):void{$s=$db->prepare('INSERT INTO app_notifications (recipient_user_id,source_type,source_id,title,body,action_path) VALUES (:recipient,:type,:source,:title,:body,:path)');$s->execute(['recipient'=>$recipient,'type'=>$type,'source'=>$source,'title'=>$title,'body'=>$body,'path'=>$path]);}
    private static function flash(string $type,string $message):void{$_SESSION['family_forms_flash']=['type'=>$type,'message'=>$message];}
    private static function takeFlash():?array{$v=$_SESSION['family_forms_flash']??null;unset($_SESSION['family_forms_flash']);return is_array($v)?$v:null;}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);exit('Forms management permission is required.');}
    private static function notFound():never{http_response_code(404);exit('Form assignment not found or not available to this account.');}
}
